enum Node {
    Leaf(String),
    Nested(Box<Node>),
}

fn traverse_safe(node: &Node) {
    let mut stack = vec![node];
    // Iterative traversal using heap-allocated Vec stack
    while let Some(current) = stack.pop() {
        match current {
            Node::Leaf(_) => {},
            Node::Nested(inner) => stack.push(inner.as_ref()),
        }
    }
}
